async preStep(target, position) {
	/* v8 ignore next -- private callers establish the running phase before proposing a step */
	if (this.phase.kind !== "running") throw new Error(`agent "${this.id}": pre-step outside running phase`);
	const signal = this.phase.abort.signal;
	const claimed = this.inbox.claim(target, position.turn);
	const selection = this.model.current();
	if (selection === void 0) throw new Error(`agent "${this.id}" has no provider/model: set AgentOptions.provider and AgentOptions.model or record a model selection`);
	const toolSet = await this.loopCtx.tools.resolve({
		agent: this,
		modelSelection: selection,
		signal
	});
	try {
		const assembly = await this.loopCtx.systemPrompt.assemble({
			...assembleContextFor(this, signal),
			modelSelection: selection,
			toolSet
		});
		signal.throwIfAborted();
		const decision = await this.dispatch.waterfall("agent/pre-step", {
			messages: claimed,
			...position,
			signal,
			modelSelection: selection
		}, () => {
			const sections = renderContextSections(assembly);
			const context = this.runtimeContext.project(joinContextSections(sections), sections);
			return Promise.resolve({
				kind: "enter",
				messages: context === void 0 ? claimed : [...claimed, context]
			});
		});
		signal.throwIfAborted();
		if (decision.kind === "reject") {
			toolSet.dispose();
			return decision;
		}
		return {
			...decision,
			assembly,
			selection,
			toolSet
		};
	} catch (error) {
		toolSet.dispose();
		throw error;
	}
}

serviceAsk:
async serviceAsk(exec, ask) {
	const approval = this.ctx.get("approval");
	if (approval === void 0) return {
		decision: {
			kind: "deny",
			reason: ask.reason ?? `tool "${exec.name}" requires approval (not yet supported)`
		},
		approvalCancelled: false
	};
	if (exec.agent === void 0) return {
		decision: {
			kind: "deny",
			reason: `tool "${exec.name}" requires approval, but the call has no agent to route it through`
		},
		approvalCancelled: false
	};
	const outcome = await approval.request({
		agent: exec.agent,
		toolName: exec.name,
		callId: exec.callId,
		...ask.reason !== void 0 ? { reason: ask.reason } : {},
		...ask.displayReason !== void 0 ? { displayReason: ask.displayReason } : {},
		signal: exec.signal
	});
	switch (outcome) {
		case "allowed-once": return {
			decision: { kind: "allow" },
			approvalCancelled: false
		};
		case "rejected": return {
			decision: {
				kind: "deny",
				reason: `the user rejected tool "${exec.name}"`
			},
			approvalCancelled: false
		};
		case "cancelled": return {
			decision: {
				kind: "deny",
				reason: `approval for tool "${exec.name}" was cancelled`
			},
			approvalCancelled: true
		};
		case "unavailable": return {
			decision: {
				kind: "deny",
				reason: `tool "${exec.name}" requires approval, but no approval channel is available`
			},
			approvalCancelled: false
		};
		default: return assertNever(outcome, "ApprovalOutcome");
	}
}

